#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);
int mx=0;vector<int>a(n);
for(int i=0;i<n;++i){scanf("%d",&a[i]);mx=max(mx,a[i]);}
vector<long long>cnt(mx+1,0);
for(int x:a)cnt[x]+=x;
long long p2=0,p1=0;
for(int v=0;v<=mx;++v){long long cur=max(p1,p2+cnt[v]);p2=p1;p1=cur;}
printf("%lld\n",p1);return 0;}

